const data=await fetch("./data/melakarta_ragas.json").then(r=>r.json());const list=document.querySelector("#raga-list"),chakra=document.querySelector("#chakra"),nameEl=document.querySelector("#name"),tamil=document.querySelector("#tamil"),aro=document.querySelector("#aro"),avaro=document.querySelector("#avaro"),meta=document.querySelector("#meta"),hear=document.querySelector("#hear"),shruti=document.querySelector("#shruti");const chakras=[...new Set(data.ragas.map(r=>r.chakra))];chakra.innerHTML=chakras.map((c,i)=>`<option value="${c}">${String(i+1).padStart(2,"0")} · ${c}</option>`).join("");const roots={C:261.63,"C♯":277.18,D:293.66,"D♯":311.13,E:329.63,F:349.23,"F♯":369.99,G:392,"G♯":415.3,A:440,"A♯":466.16,B:493.88};shruti.innerHTML=Object.keys(roots).map(k=>`<option>${k}</option>`).join("");let selected=data.ragas[14],ctx=null,timers=[];function renderList(){const rows=data.ragas.filter(r=>r.chakra===chakra.value);list.innerHTML=rows.map(r=>`<button class="list-button ${r.number===selected.number?"active":""}" data-n="${r.number}"><b>${r.number}</b><span><strong>${r.name}</strong><small lang="ta">${r.name_tamil}</small></span></button>`).join("");list.querySelectorAll("button").forEach(b=>b.onclick=()=>{selected=data.ragas.find(r=>r.number===+b.dataset.n);renderList();renderDetail()})}function renderDetail(){meta.textContent=`Mēḷakarta ${selected.number} · Chakra ${selected.chakra} / ${selected.chakra_position}`;nameEl.textContent=selected.aka?.split(" (")[0]||selected.name;tamil.textContent=selected.name_tamil;aro.textContent=selected.arohanam;avaro.textContent=selected.avarohanam}function freq(item){const m=item.note.match(/([SRGMPDN])(\d)?/),semi={S:0,R1:1,R2:2,R3:3,G1:2,G2:3,G3:4,M1:5,M2:6,P:7,D1:8,D2:9,D3:10,N1:9,N2:10,N3:11}[m[1]+(m[2]||"")];return roots[shruti.value]*2**((semi+item.octave*12)/12)}function stop(){timers.forEach(clearTimeout);timers=[];hear.textContent="▶ Hear scale";hear.classList.remove("playing")}hear.onclick=()=>{if(hear.classList.contains("playing")){stop();return}ctx??=new AudioContext();const up=selected.arohanam.split(/\s+/),down=selected.avarohanam.split(/\s+/),seq=[...up.map((note,i)=>({note,octave:i===up.length-1?1:0})),...down.map((note,i)=>({note,octave:i===0?1:0}))];hear.textContent="■ Stop";hear.classList.add("playing");seq.forEach((n,i)=>timers.push(setTimeout(()=>{const o=ctx.createOscillator(),g=ctx.createGain(),t=ctx.currentTime;o.type="sine";o.frequency.value=freq(n);g.gain.setValueAtTime(.001,t);g.gain.exponentialRampToValueAtTime(.25,t+.03);g.gain.exponentialRampToValueAtTime(.001,t+.42);o.connect(g).connect(ctx.destination);o.start();o.stop(t+.45)},i*470)));timers.push(setTimeout(stop,seq.length*470+100))};chakra.value=selected.chakra;chakra.onchange=()=>{selected=data.ragas.find(r=>r.chakra===chakra.value);renderList();renderDetail()};renderList();renderDetail();
